这一章是全书所有核心结构的   C 代码合订  ，每一段都按「定义 + 核心操作 + 一个  test xxx    测试」的方式组织，  可以直接复制到一个  .c  文件里编译运行  。

   bash
gcc 核心代码合订.c  o ds && ./ds


学习建议始终是同一句：  先盖住实现，自己照前面章节的讲义敲一遍，再回来和这里对照。   代码能默写出来，才算真正掌握。

   8.1 公共头与工具函数

所有模块共用的头文件、元素类型别名和一个打印数组的小工具。后面每段代码都默认它已经在文件顶部。

   c
 include <stdio.h 
 include <stdlib.h 
 include <string.h 

typedef int ElemType;

/  工具: 打印整型数组  /
void printArr int a  , int n   
    for  int i = 0; i < n; i++  printf "%d ", a i  ;
    printf "\n" ;



   8.2 顺序表 SqList

定长数组 +  length  计数。插入要  从后往前  挪，删除要  从前往后  挪，平均移动约一半元素，所以增删是 O n 、随机访问是 O 1 。

   c
 define MAXSIZE 100
typedef struct  
    ElemType data MAXSIZE ;
    int length;
  SqList;

void SqList init SqList  L    L  length = 0;  

/  在第 i 个位置 1..length+1 插入 e  /
int SqList insert SqList  L, int i, ElemType e   
    if  i < 1    i   L  length + 1  return 0;
    if  L  length  = MAXSIZE  return 0;
    for  int j = L  length   1; j  = i   1; j     /  从后往前挪  /
        L  data j + 1  = L  data j ;
    L  data i   1  = e;
    L  length++;
    return 1;


/  删除第 i 个元素, 值带回  e  /
int SqList delete SqList  L, int i, ElemType  e   
    if  i < 1    i   L  length  return 0;
     e = L  data i   1 ;
    for  int j = i; j < L  length; j++             /  从前往后挪  /
        L  data j   1  = L  data j ;
    L  length  ;
    return 1;


void test SqList void   
    printf "=== 1. 顺序表 ===\n" ;
    SqList L; SqList init &L ;
    for  int i = 1; i <= 5; i++  SqList insert &L, i, i   10 ; /  10 20 30 40 50  /
    printf "初始: " ; printArr L.data, L.length ;
    SqList insert &L, 3, 99 ;  printf "在第3位插99: " ; printArr L.data, L.length ;
    ElemType e;
    SqList delete &L, 1, &e ;  printf "删第1个 %d后 : ", e ; printArr L.data, L.length ;
    printf "\n" ;



